//! The designed mitral, aortic and pulmonary valves of the default pack (brief B36): generated by
//! `heartsim_geometry::valve_design` from published dimensions (`DesignedParams` and
//! `docs/research/designed-valve-leaflets.md`) on this heart's own valve discs, oriented by its
//! landmarks, and kept inside each valve's blood.
//!
//! **Orientation landmarks** (the pack has no coronary ostium, no left atrial appendage and no
//! atrial-septum label, so the cusps are named by their neighbours; research note, "Orientation
//! rules"):
//! * mitral (M-R1, M-R2): the anterior leaflet's centre toward the aortic disc centre; the
//!   anterolateral side is the side of the echo's anterolateral papillary muscle base;
//! * aortic (A-R2, A-R3): the non-coronary cusp toward the midpoint of the left and right atrial
//!   blood centroids (the atrial septum lies between them); of the other two, the right coronary
//!   cusp is the one nearer the direction of the right-ventricular blood centroid;
//! * pulmonary (Pu-R1, revised after Lis 2023): the posterior cusp is centred on the most posterior
//!   direction; of the other two, the one further to the patient's left (+x) is the left anterior,
//!   the other the right anterior.
//!
//! The cusp names are assigned in one place ([`AORTIC_CUSPS`], [`PULMONARY_CUSPS`]) so they are
//! easy to change.

use anyhow::{Context, Result, anyhow, ensure};
use glam::Vec3;
use heartsim_echo::{DesignedParams, EchoAnatomy, MotionModel, MotionParams};
use heartsim_geometry::valve::split_discs;
use heartsim_geometry::valve_design::{
    BloodMask, CuspDesign, DesignedValve, DiscFrame, MitralDesign, mitral, semilunar,
};
use heartsim_geometry::{AnatomyPack, AnimatedValve, Label, LabelVolume, MeshKind};

/// Names of the aortic cusps: (the cusp toward the atrial septum, the one toward the right
/// ventricle, the third). Research note A-R2/A-R3; no coronary ostium was checked.
pub const AORTIC_CUSPS: [&str; 3] = ["non-coronary", "right coronary", "left coronary"];
/// Names of the pulmonary cusps by position in the heart frame (research note, Pu-R1 revised,
/// after Lis 2023): (the most posterior, the one on the patient's left of the other two, the
/// third). How these map to other naming schemes is not verified.
pub const PULMONARY_CUSPS: [&str; 3] = ["posterior", "left anterior", "right anterior"];

