/// The designed valves and what to report.
#[derive(Debug)]
pub struct DesignedBake {
    pub valves: Vec<AnimatedValve>,
    pub report: Vec<String>,
}

/// The vertices of each of the four discs (mitral, tricuspid, aortic, pulmonic order).
fn disc_points(pack: &AnatomyPack) -> Result<[Vec<Vec3>; 4]> {
    let vp = pack
        .meshes
        .iter()
        .find(|m| m.kind == MeshKind::Valve && m.name == "valve_planes")
        .context("the pack has no valve_planes mesh")?;
    let discs = split_discs(&vp.mesh).context("valve_planes does not split into four discs")?;
    Ok(discs.map(|d| {
        d.iter()
            .map(|&i| Vec3::from(vp.mesh.vertices[i as usize].position))
            .collect()
    }))
}

fn centroid_of(vol: &LabelVolume, label: Label) -> Result<Vec3> {
    let mut s = glam::DVec3::ZERO;
    let mut n = 0usize;
    for (idx, l) in vol.labels.iter().enumerate() {
        if *l == label as u8 {
            let [i, j, k] = vol.coords(idx);
            s += vol.centre(i, j, k).as_dvec3();
            n += 1;
        }
    }
    ensure!(n > 0, "no {} voxels", label.name());
    Ok((s / n as f64).as_vec3())
}

fn mean(p: &[Vec3]) -> Vec3 {
    p.iter().copied().sum::<Vec3>() / p.len().max(1) as f32
}

/// Signed angle from `a` to `b` about `n`, degrees.
fn angle_about(a: Vec3, b: Vec3, n: Vec3) -> f32 {
    a.cross(b).dot(n).atan2(a.dot(b)).to_degrees()
}

/// Bake the three designed valves for `pack` (which needs its valve-plane mesh, its label
/// volumes and what the echo anatomy needs for the papillary muscles).
#[allow(clippy::too_many_lines)]
pub fn bake(pack: &AnatomyPack) -> Result<DesignedBake> {
    let d = DesignedParams::default();
    let model =
        MotionModel::new(pack, MotionParams::default()).map_err(|e| anyhow!("motion model: {e:?}"))?;
    let anatomy = EchoAnatomy::new(pack, &model, d.clone()).map_err(|e| anyhow!("echo anatomy: {e}"))?;
    let vol = &pack
        .volumes
        .as_ref()
        .context("the pack has no label volumes")?
        .heart;
    let [mitral_pts, _tricuspid_pts, aortic_pts, pulmonic_pts] = disc_points(pack)?;
    let (mc, ac) = (mean(&mitral_pts), mean(&aortic_pts));
    let lv = centroid_of(vol, Label::LvBlood)?;
    let rv = centroid_of(vol, Label::RvBlood)?;
    let la = centroid_of(vol, Label::LaBlood)?;
    let ra = centroid_of(vol, Label::RaBlood)?;
    let ao = centroid_of(vol, Label::AortaLumen)?;
    let pa = centroid_of(vol, Label::PulmonaryArteryLumen)?;
    let mut report = Vec::new();
    let mut valves = Vec::new();

    // --- mitral -------------------------------------------------------------------------------
    let disc = DiscFrame::new(&mitral_pts, lv).context("degenerate mitral disc")?;
    let n = disc.normal();
    let ua = disc
        .in_plane(ac - disc.centre())
        .context("aortic disc above the mitral centre")?;
    let pap = anatomy.papillary_muscles();
    let side = n.cross(ua);
    let al_base = pap[0].a_mm - disc.centre();
    let pm_base = pap[1].a_mm - disc.centre();
    let (mut al_dir, mut rule) = (if side.dot(al_base) >= 0.0 { side } else { -side }, "M-R2");
    if al_dir.dot(pm_base) >= 0.0 {
        // both muscles on one side: an unusual pack; fall back to +x = lateral
        al_dir = if side.x >= 0.0 { side } else { -side };
        rule = "fallback +x";
    }
    let p = MitralDesign {
        anterior_length_mm: d.mitral_anterior_length_mm,
        posterior_length_mm: d.mitral_posterior_length_mm,
        coaptation_mm: d.mitral_coaptation_mm,
        open_angle_deg: d.open_angle_from_axis_deg,
        ..MitralDesign::default()
    };
    let mask = BloodMask {
        volume: vol,
        labels: &[Label::LvBlood, Label::LaBlood],
    };
    let tips = [pap[0].b_mm, pap[1].b_mm];
    let m = mitral(&disc, ua, al_dir, tips, &p, Some(&mask)).map_err(|e| anyhow!("{e}"))?;
    report.push(format!(
        "mitral: disc centre {:.1?}, normal {:.2?} (toward the LV blood centroid), mean rim radius {:.1} mm, \
         area {:.0} mm²; anterior leaflet toward the aortic disc (M-R1), anterolateral side by the anterolateral \
         papillary muscle base ({rule}); chordae to the echo's muscle tips {:.1?} and {:.1?}",
        disc.centre(),
        n,
        disc.mean_radius_mm(),
        disc.area_mm2(),
        tips[0],
        tips[1]
    ));
    push(&mut report, &mut valves, m);

    // --- aortic -------------------------------------------------------------------------------
    let disc = DiscFrame::new(&aortic_pts, ao).context("degenerate aortic disc")?;
    let n = disc.normal();
    let septum = (la + ra) * 0.5;
    let w_n = disc
        .in_plane(septum - disc.centre())
        .or_else(|| disc.in_plane(la - disc.centre()))
        .context("no direction to the atria")?;
    let dir = |k: usize| glam::Quat::from_axis_angle(n, (120.0 * k as f32).to_radians()) * w_n;
    let to_rv = disc
        .in_plane(rv - disc.centre())
        .context("no direction to the RV")?;
    // cusp 1 or 2 is the right coronary: the nearer to the RV direction
    let right_is_1 = dir(1).dot(to_rv) >= dir(2).dot(to_rv);
    let names = if right_is_1 {
        [AORTIC_CUSPS[0], AORTIC_CUSPS[1], AORTIC_CUSPS[2]]
    } else {
        [AORTIC_CUSPS[0], AORTIC_CUSPS[2], AORTIC_CUSPS[1]]
    };
    let cusp = CuspDesign {
        effective_height_mm: d.aortic_effective_height_mm,
        ..CuspDesign::default()
    };
    let mask = BloodMask {
        volume: vol,
        labels: &[Label::LvBlood, Label::AortaLumen],
    };
    let a = semilunar("aortic", names, &disc, w_n, &cusp, Some(&mask)).map_err(|e| anyhow!("{e}"))?;
    // the commissure between the non-coronary and the left coronary cusp, against the mitral
    let left = if right_is_1 { 2 } else { 1 };
    let comm = disc
        .in_plane(dir(0) + dir(left))
        .context("degenerate commissure")?;
    let to_mitral = disc
        .in_plane(mc - disc.centre())
        .context("no direction to the mitral")?;
    report.push(format!(
        "aortic: disc centre {:.1?}, mean rim radius {:.1} mm, area {:.0} mm²; non-coronary cusp toward the midpoint \
         of the LA and RA blood centroids (A-R2), {:.0}° from the direction to the RV blood centroid; right coronary \
         cusp the one nearer the RV (A-R3); the non-coronary/left-coronary commissure lies {:.0}° from the direction \
         to the mitral centre (check: within 45°); no coronary ostium in the pack, the names are by neighbours",
        disc.centre(),
        disc.mean_radius_mm(),
        disc.area_mm2(),
        angle_about(w_n, to_rv, n).abs(),
        angle_about(comm, to_mitral, n).abs()
    ));
    push(&mut report, &mut valves, a);

    // --- pulmonary ----------------------------------------------------------------------------
    let disc = DiscFrame::new(&pulmonic_pts, pa).context("degenerate pulmonary disc")?;
    let n = disc.normal();
    // Pu-R1 revised (Lis 2023, names by position): cusp 0 centred on the most posterior in-plane
    // direction (−z); of cusps 1 and 2, the one with the larger x (the patient's left) is the
    // left anterior
    let w_p = disc.in_plane(-Vec3::Z).context("the pulmonary axis along z")?;
    let dir = |k: usize| glam::Quat::from_axis_angle(n, (120.0 * k as f32).to_radians()) * w_p;
    let left_is_1 = dir(1).x >= dir(2).x;
    let names = if left_is_1 {
        [PULMONARY_CUSPS[0], PULMONARY_CUSPS[1], PULMONARY_CUSPS[2]]
    } else {
        [PULMONARY_CUSPS[0], PULMONARY_CUSPS[2], PULMONARY_CUSPS[1]]
    };
    // the geometric height measured on pulmonary valves (Lis 2023 Table 1: 15.5 mm on a 23.4 mm
    // ring, 0.66 of its diameter), scaled to this disc; 120° per cusp (L4's 124.5 / 110.5 / 125°
    // not used: a symmetric designed valve)
    let cusp = CuspDesign {
        effective_height_mm: d.pulmonary_effective_height_mm,
        geometric_height_ratio: Some(0.66),
        ..CuspDesign::default()
    };
    let mask = BloodMask {
        volume: vol,
        labels: &[Label::RvBlood, Label::PulmonaryArteryLumen],
    };
    let pv = semilunar("pulmonary", names, &disc, w_p, &cusp, Some(&mask)).map_err(|e| anyhow!("{e}"))?;
    report.push(format!(
        "pulmonary: disc centre {:.1?}, mean rim radius {:.1} mm, area {:.0} mm²; posterior cusp on the most \
         posterior direction, left anterior and right anterior by x (Pu-R1 revised, Lis 2023's positional names); the \
         mapping to other naming schemes is not verified",
        disc.centre(),
        disc.mean_radius_mm(),
        disc.area_mm2()
    ));
    push(&mut report, &mut valves, pv);
    Ok(DesignedBake { valves, report })
}

fn push(report: &mut Vec<String>, valves: &mut Vec<AnimatedValve>, d: DesignedValve) {
    report.extend(d.report);
    let v = d.valve;
    report.push(format!(
        "{}: {} vertices ({} leaflet), {} triangles, {} chordae, {} shapes, quantum {:.5} mm, {} bytes",
        v.name,
        v.rest_mm.len(),
        v.leaflet_vertices,
        v.triangles.len(),
        v.chordae.len(),
        v.keyframe_count(),
        v.quantum_mm,
        v.encode().len()
    ));
    valves.push(v);
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Brief B36: the designed valves baked from the committed default pack are the committed
    /// files, byte for byte (the generator is a pure function of the pack; the generator's own
    /// test checks that two runs agree).
    #[test]
    fn the_designed_bake_reproduces_the_committed_files() {
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("..");
        let dir = root.join("assets/anatomy/default");
        let pack = AnatomyPack::load(&dir).expect("default pack");
        let baked = bake(&pack).expect("bake");
        assert_eq!(baked.valves.len(), 3);
        for v in &baked.valves {
            let file = heartsim_geometry::pack::valve_file(&v.name);
            let committed = std::fs::read(dir.join(&file)).expect("committed valve");
            assert!(v.encode() == committed, "{file} is not what the bake gives");
        }
    }
}
